import json, sys, time, urllib.request, urllib.error, datetime, decimal, email.utils

BASE = 'http://localhost:8080'
TOKEN = None

def retry_delay(headers, attempt):
    value = headers.get('Retry-After') if headers else None
    if value:
        try:
            return max(0.0, float(value))
        except ValueError:
            try:
                dt = email.utils.parsedate_to_datetime(value)
                return max(0.0, (dt - datetime.datetime.now(datetime.timezone.utc)).total_seconds())
            except Exception:
                pass
    return min(2 ** min(attempt, 5), 30)

def raw_request(method, path, body=None, auth=False):
    global TOKEN
    attempt = 0
    while True:
        headers = {'Accept': 'application/json'}
        data = None
        if body is not None:
            headers['Content-Type'] = 'application/json'
            data = json.dumps(body).encode()
        if auth:
            if TOKEN is None:
                TOKEN = [REDACTED_SECRET]
            headers['Authorization'] = 'Bearer ' + TOKEN
        req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.headers, resp.read()
        except urllib.error.HTTPError as e:
            payload = e.read()
            if e.code == 401 and auth:
                TOKEN = None
                attempt += 1
                if attempt > 10:
                    raise RuntimeError('too many authentication failures')
                continue
            if e.code == 429 or 500 <= e.code < 600:
                delay = retry_delay(e.headers, attempt)
                print(f'HTTP {e.code} for {path}; retrying in {delay:g}s', file=sys.stderr)
                time.sleep(delay)
                attempt += 1
                continue
            raise RuntimeError(f'HTTP {e.code} for {path}: {payload[:300]"'!r}'"')
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            delay = retry_delay({}, attempt)
            print(f'Request error for {path}: {e}; retrying in {delay:g}s', file=sys.stderr)
            time.sleep(delay)
            attempt += 1

def get_json(path, auth=False):
    status, headers, payload = raw_request('GET', path, auth=auth)
    return json.loads(payload)

def fetch_token():
    while True:
        try:
            status, headers, payload = raw_request('POST', '/token', {})
            tok = json.loads(payload)['token']
            print('Fetched service token', file=sys.stderr)
            return tok
        except Exception as e:
            print(f'Token request failed: {e}; retrying', file=sys.stderr)
            time.sleep(2)

start = datetime.datetime(2025, 3, 1, tzinfo=datetime.timezone.utc)
end = datetime.datetime(2025, 6, 1, tzinfo=datetime.timezone.utc)
seen_ids = set()
duplicates = 0
qualifying = []
path = '/orders?page=1'
pages = 0
while path:
    data = get_json(path, auth=True)
    pages += 1
    if data.get('page') "'!= pages:
        raise RuntimeError(f'"'unexpected page sequence: expected {pages}, got {data.get(\"page\")}')
    for order in data['items']:
        oid = order['id']
        if oid in seen_ids:
            duplicates += 1
            continue
        seen_ids.add(oid)
        if order['status'] "'!= '"'shipped':
            continue
        placed = datetime.datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(datetime.timezone.utc)
        if start <= placed < end:
            qualifying.append(order)
    path = data.get('next')
print(f'Fetched {pages} pages; {len(seen_ids)} unique orders; {duplicates} duplicate listings; {len(qualifying)} qualifying orders', file=sys.stderr)

customers = {}
by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = get_json('/customers/' + urllib.parse.quote(str(cid), safe=''), auth=True)
    customer = customers[cid]
    amount = decimal.Decimal(order['amount_cents']) * (decimal.Decimal(100 - customer['discount_pct']) / decimal.Decimal(100))
    discounted = int(amount.quantize(decimal.Decimal('1'), rounding=decimal.ROUND_HALF_UP))
    region = customer['region']
    if region not in by_region:
        raise RuntimeError(f'unknown region {region"'!r}'"')
    by_region[region] += discounted
result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
assert result['total_cents'] == sum(result['by_region'].values())
with open('/workspace/result.json', 'w') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
print(json.dumps(result, indent=2), file=sys.stderr)
print(f'Cached {len(customers)} customer records', file=sys.stderr)
